/*
 * A208522  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A208522; see the Formula section.
 * https://oeis.org/A208522
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the enumeration of the coefficients of the * polynomials
 *            u(k,x) generated by * u(1,x) = 1, v(1,x) = 1 * u(k,x) = u(k-1,x)
 *            + x*v(k-1,x) * v(k,x) = 2x*u(k-1,x) + x*v(k-1,x) + 1 * Each row
 *            k lists the coefficients of u(k,x) from the constant term * to
 *            the highest power of x. The sequence is...
 * Range:     u8 n <= 42, u16 n <= 66, u32 n <= 66, u64 n <= 66, u128 n <= 66,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n < 1) return 0; /* safety for n == 0 */

    /* Find the row r (1‑based) such that r*(r+1)/2 ≥ n */
    idx_t r = 1;
    while ((seq_t)r * (r + 1) / 2 < n) r++;

    /* Elements before row r */
    idx_t prev_total = r * (r - 1) / 2;
    idx_t col = n - prev_total - 1; /* 0‑based column within row r */

    /* Temporary storage for two consecutive rows; size 200 exceeds
     * the maximum needed for n ≤ 10000 (row 141). */
    seq_t prev_u[200] = {0};
    seq_t prev_v[200] = {0};
    seq_t cur_u[200]  = {0};
    seq_t cur_v[200]  = {0};

    /* Base row 1 */
    prev_u[0] = 1;
    prev_v[0] = 1;
    idx_t prev_len = 1;

    if (r == 1) return prev_u[0];

    for (idx_t row = 2; row <= r; ++row) {
        cur_u[0] = prev_u[0];
        cur_v[0] = (seq_t)1;

        for (idx_t j = 1; j < row; ++j) {
            seq_t u_prev_j = (j < prev_len) ? prev_u[j] : 0;
            cur_u[j] = u_prev_j + prev_v[j - 1];
            cur_v[j] = (seq_t)2 * prev_u[j - 1] + prev_v[j - 1];
        }

        for (idx_t j = 0; j < row; ++j) {
            prev_u[j] = cur_u[j];
            prev_v[j] = cur_v[j];
        }
        prev_len = row;
    }

    return prev_u[col];
}
